use std :: collections :: HashMap ; use std :: fs ; use std :: process :: Command ; use std :: path :: Path ; fn test_group_classification () -> Result < () , String > { let test_cases = vec ! [(0.5 , "Cyclic") , (1.5 , "Alternating") , (2.5 , "Lie Type") , (3.5 , "Sporadic") ,] ; for (complexity , expected_family) in test_cases { let family = match complexity { c if c < 1.0 => "Cyclic" , c if c < 2.0 => "Alternating" , c if c < 3.0 => "Lie Type" , _ => "Sporadic" , } ; assert_eq ! (family , expected_family) ; } println ! ("    ✓ Group classification test passed") ; Ok (()) }